import { isMazeEntry, MAZE_ENTRY_RULES } from './maze-rules.js';
import { roleTitle } from './interaction-ui-v40.js';
import { selectSection } from './interface-workspaces.js';
import { isRadiant } from './radiant-descent.js';
import { renderRadiantPanel } from './radiant-ui.js';
import { equipmentComparator } from './gear-comparison.js';
import { renderEquipmentComparison } from './equipment-comparison-ui.js';
import { renderAreaScene } from './area-scenes.js';
import { gearScore, getGearItem } from './gear.js';
import { curseLawAt } from './curses.js';
import { partyPreparation } from './combat.js';
import { personalityImpactText } from './personality.js';
import { faithView } from './faith.js';
import { realmView } from './realm.js';
import { adventureView } from './adventuring.js';
import { renderAvatar } from './avatar.js';
import { characterDetail } from './characters.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const heading=(title,subtitle,eyebrow)=>`<div class="chapter-heading"><span class="eyebrow">${e(eyebrow)}</span><h1>${e(title)}</h1><p class="muted">${e(subtitle)}</p></div>`;
const fallbackActions=(s,rows)=>`<div class="quick-actions">${rows.map(a=>`<button type="button" class="activity-row" data-op="activity" data-id="${e(a.id)}" ${a.disabledReason?'disabled':''}><span class="activity-symbol" aria-hidden="true">†</span><span class="activity-copy"><strong>${e(a.label)}</strong><span>${e(a.description)}</span>${personalityImpactText(s,{kind:'action',id:a.id})?`<small class="trait-preview">${e(personalityImpactText(s,{kind:'action',id:a.id}))}</small>`:''}${a.disabledReason?`<small class="disabled-reason">${e(a.disabledReason)}</small>`:''}</span><span class="activity-cost">${a.days?`${a.days}d`:'Now'}${a.cost?`<br>${a.cost}g`:''}</span><span class="choice-arrow" aria-hidden="true">→</span></button>`).join('')}</div>`;
const portrait=(p,detail)=>`<div class="rpg-person">${renderAvatar(p,{size:'medium',age:p.age||30})}<div><h3>${e(p.name)}</h3><p class="muted">${e(detail||p.disposition)}</p><p class="small-copy">${e(characterDetail(p))}</p></div></div>`;
export function merchantPanel(s,allActions,ui={}){
  const compare=equipmentComparator(s);
  const actions=ui.actionCards||((rows)=>fallbackActions(s,rows)+rows.filter(a=>a.id.startsWith('gear_buy_')).map(a=>renderEquipmentComparison(compare(a.id.slice(9)),{e},{purchase:true})).join(''));
  const v=realmView(s),m=v?.merchant;if(!m||['destroyed','evacuated'].includes(s.world.locations.find(p=>p.id===s.locationId).status))return `<section class="panel"><h2>No open shop here</h2><p class="muted">Surviving settlements have their own merchants and seasonal stock.</p></section>`;
  return `<section class="panel"><div class="eyebrow">THE LOCAL SHOP</div>${portrait(m,`${m.disposition} merchant · ${v.region.name}`)}<p>${e({generous:'They leave a little room in the price for a hungry traveler.',exacting:'Every blade is tested and every coin weighed.',secretive:'Their finest goods are kept beneath a folded dark cloth.',gregarious:'They know half the caravans and remember a customer’s face.',wary:'They watch the road while answering your offer.',ambitious:'They intend this small stall to become the largest house in the region.'}[m.disposition])}</p><p class="muted small-copy">Stock changes with the season. Purchases, sales and scarce supplies are remembered.</p>${actions(allActions.filter(a=>a.id.startsWith('realm_potion')||a.id.startsWith('realm_ration')||a.id.startsWith('gear_buy_')))}<details class="market-sales"><summary>Sell Carried Gear &amp; Loot</summary>${actions(allActions.filter(a=>a.id.startsWith('realm_sell')))||'<p>You have nothing available to sell here.</p>'}</details></section>`;
}
export function adventurePage(s,allActions,ui={}){
  const actions=ui.actionCards||((rows)=>fallbackActions(s,rows));
  const v=adventureView(s);if(!v)return '';
  const prep=partyPreparation(s),readyPanel=`<details class="panel"><summary>Party preparation · ${prep.participants.length} ready · ${prep.potions} draughts</summary>${prep.participants.map(p=>`<p>${e(p.name)} · ${e(roleTitle(p.role))} · Health ${p.hp}/${p.maxHp} · Focus ${p.mp}/${p.maxMp}</p>`).join('')}${prep.unready.map(p=>`<p>${e(p.name)} · ${e(p.reason)}</p>`).join('')}<p>${prep.formationEarned?'Earned covering formation available.':'Further formation work can earn a covering technique.'} Equipment ${Object.values(prep.equipment).filter(Boolean).map(id=>e(getGearItem(s,id)?.name||id)).join(', ')||'not yet equipped'}. Threats stay unknown until encountered; withdrawal remains available.</p></details>`;
  const contracts=v.contracts.filter(c=>!['done','abandoned'].includes(c.status));
  const overview=`<div class="rpg-summary"><span>${s.hero.hp}/${s.hero.maxHp} health · ${s.hero.mp}/${s.hero.maxMp} magic</span><span>${s.hero.potions} potions · ${s.companions.filter(p=>p.recruited&&p.active).length} companions</span><span>${v.rations} expedition rations</span><span>${v.loot.length} relics in your pack</span><span>${v.contracts.filter(c=>['active','ready'].includes(c.status)).length}/4 undertakings</span></div>${s.event||s.battle?'<p class="notice">Finish the current encounter in Life to continue.</p>':''}`,expedition=v.expedition?`<section class="panel"><h2>The ${e(v.expedition.theme)} descent</h2><p>Floor ${v.expedition.floor} · Chamber ${v.expedition.room+1} · ${v.expedition.cleared.length} rooms explored · Gear score ${gearScore(s)}</p>${renderAreaScene(s,{e},{dungeon:{room:{title:s.event?.title||'The current chamber'}}})}${isRadiant(v.expedition)?(!s.event?renderRadiantPanel(s,{e}):''):`<div class="descent-room-track">${Array.from({length:6},(_,i)=>`<span class="${i===v.expedition.room?'current':v.expedition.cleared.includes(v.expedition.floor+':'+i)?'cleared':''}">${i+1}<small>${i===v.expedition.room?'You':v.expedition.cleared.includes(v.expedition.floor+':'+i)?'Cleared':'Unknown'}</small></span>`).join('')}</div>`}${s.event&&ui.encounter?ui.encounter():''}${actions(allActions.filter(a=>a.id.startsWith('adventure_')))}</section>`:'';
  return heading('Contracts & delves','Choose a petition, prepare for the road, or review what you brought home.','BEYOND YOUR HEARTH')+selectSection(ui,{board:overview+(expedition||`<section><div class="section-heading"><h2>The contract board</h2><span class="muted">This season’s petitions</span></div><div class="rpg-contracts">${contracts.map(c=>`<article class="panel">${portrait(c.giver,c.type==='bounty'?'Bounty petitioner':'Contract giver')}<span class="badge">${e(c.status)} · Tier ${c.tier}</span><h3>${e(c.title)}</h3><p>${e(c.brief)}</p><dl class="rpg-facts"><div><dt>Destination</dt><dd>${e(c.destination)}</dd></div><div><dt>Payment</dt><dd>${c.reward} gold${c.proof?.captured?' + 15 for a living captive':''}</dd></div><div><dt>Return to</dt><dd>${e(c.board)}</dd></div></dl><button type="button" class="button ghost small" data-op="quest-location" data-id="${e(c.destinationId)}">Find the destination →</button>${actions(allActions.filter(a=>a.id.endsWith('_'+c.id)))}</article>`).join('')||'<p class="muted">No open board here. Visit a settlement for petitions or roam freely.</p>'}</div></section>`),delves:expedition||`<section class="panel"><h2>The uncharted depths</h2><p>${e(isMazeEntry(s,'adventure_descend')?MAZE_ENTRY_RULES+' Entry costs one day and 1 ration, not a ration per lower floor. Camp uses an attended day and a kit night if available; a bare rest is weaker.':s.mazeBook?'Continue the saved expedition using its recorded rooms and provisions.':'Six floors of branching routes, physical landmarks and finite supplies. Return with a recovered object, a survey account or completed repairs; bring provisions for new depths and camps.')}</p>${actions(allActions.filter(a=>a.id==='adventure_descend'||a.id.startsWith('adventure_roam_')))}</section>`,preparation:readyPanel,loot:`<section class="panel"><h2>Relics &amp; spoils</h2>${v.loot.map(l=>`<div class="rpg-loot"><strong>${e(l.name)}</strong><span>${l.stolen?'Stolen · ':''}${l.value}g assessed value</span></div>`).join('')||'<p class="muted">Coffers and victories bring back distinct relics, materials and occasional equipment.</p>'}<button type="button" class="button secondary" data-op="tab" data-id="inventory">Open your pack &amp; sell →</button></section>`});
}
export function realmPage(s,allActions,ui={}){
  const actions=ui.actionCards||((rows)=>fallbackActions(s,rows));
  const v=realmView(s);if(!v)return '';
  const p=s.justice?.prison;
  if(p)return heading('Days behind the iron door.','The world and your family continue while you serve. Your possessions wait for release.','REGIONAL CUSTODY')+`<section class="panel">${portrait(p.warden,'Gaoler of this region')}<p>${e(p.reason)}</p><div class="rpg-summary"><strong>${p.servedDays} / ${p.totalDays} days served</strong><span>${p.totalDays-p.servedDays} remaining</span></div>${portrait(p.inmate,'A fellow prisoner')}<p class="small-copy">${e(curseLawAt(s)?.text||'')}</p>${actions(allActions.filter(a=>a.id.startsWith('justice_')))}</section>`;
  const region=v.region;
  return heading(region.name,region.description,'LAWS & FAITHS')+selectSection(ui,{
law:`<section class="panel">${portrait({...region.ruler,age:region.ruler.baseAge+Math.floor((s.day-region.ruler.createdDay)/365)},`Ruler · ${region.regime}`)}<div class="rpg-summary"><span>${e(v.site.phase)}</span><span>Prosperity ${v.site.prosperity}/100</span><span>Security ${v.site.security}/100</span></div><h3>${e(region.law.name)}</h3>${region.occupation?`<p class="small-copy">World year ${Math.floor(region.occupation.day/365)}: ${e(region.occupation.author)} signed a ${e(region.occupation.policy)} settlement. The local population keeps its heritage.</p>`:''}<p>${region.law.theftFinePerEvidence} gold restitution and ${region.law.prisonDaysPerEvidence} days of custody per recorded evidence. Public magic is ${e(region.law.publicMagic)}. ${region.law.contrabandAllowed?'Contraband trade is tolerated.':'Stolen goods risk a local report.'}</p><p class="small-copy">${e(curseLawAt(s)?.text||'')}</p>${actions(allActions.filter(a=>a.id.startsWith('justice_')||['realm_invest','realm_rebuild','realm_relief','realm_negotiate','realm_raid','realm_charter','realm_seize','realm_govern_care','realm_govern_tithe'].includes(a.id)))}</section>`,
faith:`<section class="panel"><div class="eyebrow">THE ALTAR YOU CHOOSE</div><h2>${v.faith?e(v.faith.name):'No sworn congregation'}</h2><p class="small-copy">Upbringing: ${e(s.hero.belief||'unrecorded')} · Personal temperament: ${e(s.hero.temperament||'unrecorded')} · Formal membership: ${v.faith?e(v.faith.name):'none'}. Leaving an institution preserves the life you already lived.</p>${v.faith?`<p>${e(v.faith.doctrine)}</p><p class="muted">${e(v.faith.ritualDescription)}</p>`:'<p class="muted">Any ancestry may follow, leave or change a tradition. A faith offers practices; your deeds decide who you become.</p>'}${actions(allActions.filter(a=>/^realm_(join_|ritual|leavefaith|petition|inquiry|report_)|^faith_/.test(a.id)))}${clothPanel(s,e)}${s.realm.petition?`<p class="notice">${e(s.realm.petition.keeperName)}’s request: ${s.realm.petition.stage==='field'?'inquire at '+e(s.world.locations.find(p=>p.id===s.realm.petition.destinationId).name):'return to '+e(s.world.locations.find(p=>p.id===s.realm.petition.boardId).name)}.</p>`:''}</section>`,
regions:`<section><h2>The six regions</h2><div class="rpg-regions">${v.regions.map(r=>`<article class="panel"><span class="eyebrow">${e(r.regime)} · ${e(r.tradeFocus)}</span><h3>${e(r.name)}</h3><p>${e(r.climate)} · ${e(r.resource)}</p><p class="muted">${e(r.ruler.name)} · ${e(v.faiths.find(f=>f.id===r.faithId).name)}</p></article>`).join('')}</div></section>`,
conflict:`<section class="panel"><h2>Wars &amp; changing hearths</h2>${v.wars.slice(-6).reverse().map(w=>`<p><strong>${e(v.regions.find(r=>r.id===w.a).name)} / ${e(v.regions.find(r=>r.id===w.b).name)}</strong> · ${e(w.status)} · Recorded cause: ${e(w.grievance||s.rpg?.warAccounts?.find(a=>a.warId===w.id)?.cause||'Cause unrecorded')}${w.victor?' · Victorious: '+e(v.regions.find(r=>r.id===w.victor).name):''}</p>`).join('')||'<p class="muted">The banners are quiet. Rivalries will change as years pass.</p>'}${v.history.map(h=>`<p class="small-copy">Year ${Math.floor(h.day/365)} · ${e(h.text)}</p>`).join('')}</section>`
  });
}
/** The cloth on the realm page: the rank, the house, the prior and the wing, the people, what the house remembers. */
function clothPanel(s,e){
  const v=faithView(s); if(!v) return '';
  const parts=[], m=v.member;
  if(m){
    const vows=m.vows?` The vows: poverty, ${m.vows.chastity?'chastity':'chastity read kindly'}, obedience.`:'';
    parts.push(`<div class="schooling-row"><span class="eyebrow">THE CLOTH</span><p>${e(`${m.title[0].toUpperCase()}${m.title.slice(1)} of ${m.house}, ${m.years<1?'this year':m.years+' year'+(m.years===1?'':'s')} in the grey, ${{given:'given as a child',called:'from the shrine door',ordained:'by the Seminary’s orders',vowed:'on a vow made in the dark',heir:'by the name in the house’s book'}[m.how]}. The house’s seat is ${m.seatName}${m.shrineName?`; you keep the shrine at ${m.shrineName}`:''}. Your standing in the house is ${m.standing>=65?'high':m.standing>=45?'fair':'thin'}.${vows}${m.tithe.arrears?` ${m.tithe.arrears} season${m.tithe.arrears===1?'':'s'} of tithe owed.`:''}${m.penance?` ${m.penance.days} days of penance owed.`:''}`)}</p></div>`);
    parts.push(`<div class="schooling-row"><span class="eyebrow">THE HOUSE</span><p><strong>${e(m.prior.name)}</strong>, ${m.rank==='prior'?'yourself, prior':'prior'}, of ${e(m.priorWing)}: the house should ${e(m.wingLine||'keep its lamps')}.${m.rival&&m.rank!=='prior'?` <strong>${e(m.rival.name)}</strong> at the other lamp: ${m.rival.sermons.filter(x=>x.won).length} sermon${m.rival.sermons.filter(x=>x.won).length===1?'':'s'} to you, ${m.rival.sermons.filter(x=>!x.won).length} to them.`:''}${m.penitent?` <strong>${e(m.penitent.name)}</strong> comes to the shrine door.`:''}${m.doubter?` <strong>${e(m.doubter.name)}</strong>, who has no light behind the lamps.`:''}</p></div>`);
  } else if(v.heir) parts.push(`<div class="schooling-row"><span class="eyebrow">THE HOUSE’S BOOK</span><p>${e(v.heir.left==='kept'?`${v.heir.from}’s name is in the book of ${v.heir.house}. Ask at the shrine and the house will find it.`:v.heir.left==='defrocked'?`${v.heir.from} was put out of ${v.heir.house}. The Order remembers the name.`:`${v.heir.from} left ${v.heir.house}.`)}</p></div>`);
  if(v.past.length) parts.push(`<div class="schooling-row"><span class="eyebrow">OUT OF THE GREY</span>${v.past.map(p=>`<p>${e(`${p.house[0].toUpperCase()}${p.house.slice(1)}: ${p.rank}, ${p.left}.`)}</p>`).join('')}</div>`);
  const memories=v.threads.flatMap(t=>t.memory).concat(v.history.map(h=>h.text)).slice(-4);
  if(memories.length) parts.push(`<div class="schooling-row"><span class="eyebrow">WHAT THE HOUSE REMEMBERS</span>${memories.map(x=>`<p class="small-copy">${e(x)}</p>`).join('')}</div>`);
  return parts.join('');
}
